import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

public class TemperatureTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        Temperature a = new Temperature(12);
        Temperature b = new Temperature(12);
        Temperature cold = new Temperature(-5);

        check("toString() of 12", "12C", a.toString());
        check("equals() on equal values", true, a.equals(b));
        check("equals() on different values", false, a.equals(cold));
        check("equals(null)", false, a.equals(null));
        check("equal objects share a hash code", true, a.equals(b) && a.hashCode() == b.hashCode());

        check("compareTo sign, colder first", -1, Integer.signum(cold.compareTo(a)));

        List<Temperature> list = new ArrayList<>();
        list.add(new Temperature(20));
        list.add(new Temperature(-5));
        list.add(new Temperature(12));
        list.add(new Temperature(0));
        list.add(new Temperature(35));
        Collections.sort(list);
        check("sorted list", "[-5C, 0C, 12C, 20C, 35C]", list.toString());

        Set<Temperature> set = new HashSet<>();
        set.add(new Temperature(12));
        set.add(new Temperature(12));
        set.add(new Temperature(20));
        check("HashSet removes the duplicate", 2, set.size());

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

